// DogworksTV · lista de jogos co-op/multiplayer
// - Base list: data/games.json (generated by scripts/build-library.mjs).
// - Favorites, added games, edits and hidden games: the Steam account (D1) when signed in,
//   localStorage when signed out (moved into the account on sign-in). Export/import as backup.
// - Display preferences (sort, filters): always localStorage.
// - Steam sign-in, "Eu tenho", who owns each game and prices: Worker API (/api/*) + D1.

const STORAGE_KEY = 'dogworks-games:v1';

const svg = (paths) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths}</svg>`;

const ICON = {
  users: svg('<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'),
  sofa: svg('<path d="M20 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v3"/><path d="M2 11a2 2 0 0 1 4 0v2h12v-2a2 2 0 0 1 4 0v5a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2Z"/><path d="M4 18v2M20 18v2"/>'),
  swords: svg('<path d="M14.5 17.5 3 6V3h3l11.5 11.5M13 19l6-6M16 16l4 4M19 21l2-2"/><path d="M14.5 6.5 18 3h3v3l-3.5 3.5M5 14l4 4M7 17l-3 3M3 19l2 2"/>'),
  crown: svg('<path d="m2 4 3 12h14l3-12-6 7-4-7-4 7-6-7Z"/><path d="M5 20h14"/>'),
  gamepad: svg('<path d="M6 12h4M8 10v4M15 13h.01M18 11h.01"/><rect width="20" height="12" x="2" y="6" rx="2"/>'),
  info: svg('<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>'),
  star: svg('<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>'),
  edit: svg('<path d="M17 3a2.85 2.85 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/>'),
  eyeOff: svg('<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68M6.61 6.61A13.53 13.53 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61M2 2l20 20"/>'),
  eye: svg('<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'),
  trash: svg('<path d="M3 6h18M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>'),
  close: svg('<path d="M18 6 6 18M6 6l12 12"/>'),
  check: svg('<path d="M20 6 9 17l-5-5"/>'),
  tag: svg('<path d="M12.6 2.6A2 2 0 0 0 11.2 2H4a2 2 0 0 0-2 2v7.2a2 2 0 0 0 .6 1.4l8.7 8.7a2.4 2.4 0 0 0 3.4 0l6.6-6.6a2.4 2.4 0 0 0 0-3.4Z"/><circle cx="7.5" cy="7.5" r=".5"/>'),
  heart: svg('<path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/>'),
  link: svg('<path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>'),
  trend: svg('<path d="m22 17-8.5-8.5-5 5L2 7"/><path d="M16 17h6v-6"/>'),
};

const LOGO = (store) => `<span class="logo logo-${store}" aria-hidden="true"></span>`;

const CATEGORIES = [
  { id: 'coop-online', label: 'Co-op online', icon: ICON.users },
  { id: 'coop-local', label: 'Co-op local', icon: ICON.sofa },
  { id: 'pvp', label: 'PvP', title: 'Competitivo (PvP)', icon: ICON.swords },
  { id: 'estrategia', label: 'Estratégia', icon: ICON.crown },
  { id: 'party', label: 'Party', title: 'Party & versus local', icon: ICON.gamepad },
  { id: 'outros', label: 'Outros', title: 'Multiplayer secundário', icon: ICON.info },
];
const CATEGORY_BY_ID = Object.fromEntries(CATEGORIES.map((c) => [c.id, c]));

const TAGS = {
  'coop-online': { label: 'Co-op online' },
  'coop-local': { label: 'Co-op local', cls: 'local' },
  'coop-lan': { label: 'Co-op LAN' },
  'split-screen': { label: 'Tela dividida', cls: 'local' },
  'pvp-online': { label: 'PvP online', cls: 'pvp' },
  'pvp-local': { label: 'PvP local', cls: 'pvp' },
  'pvp-lan': { label: 'PvP LAN', cls: 'pvp' },
  crossplay: { label: 'Crossplay' },
  mmo: { label: 'MMO' },
};

const PLATFORMS = [
  { id: 'steam', label: 'Steam' },
  { id: 'epic', label: 'Epic' },
  { id: 'outra', label: 'Outra' },
];

/* ---------------- helpers ---------------- */

const $ = (sel, root = document) => root.querySelector(sel);

const esc = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const norm = (s = '') =>
  String(s)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[®™©]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const compact = (s) => norm(s).replace(/ /g, '');

function safeUrl(u) {
  if (!u) return '';
  try {
    const url = new URL(u);
    if (url.protocol === 'https:' || url.protocol === 'http:') return url.href;
  } catch {}
  return '';
}

const epicSearchUrl = (name) =>
  `https://store.epicgames.com/pt-BR/browse?q=${encodeURIComponent(name)}&sortBy=relevancy&sortDir=DESC`;

const steamAppId = (url) => (String(url || '').match(/store\.steampowered\.com\/app\/(\d+)/) || [])[1] || null;

// Same game across users: Steam appid when known, else the normalized name.
const gameKey = (g) => {
  const id = steamAppId(g.steamUrl);
  return id ? `steam:${id}` : `name:${compact(g.name).slice(0, 120)}`;
};

// Epic blocks reading its store pages, so an Epic link only gives us the product slug.
// "…/p/borderlands-3" → "borderlands 3", which is then searched on Steam.
function epicLinkInfo(text) {
  const m = String(text || '').match(/epicgames\.com\/(?:[a-z]{2}(?:-[A-Z]{2})?\/)?(?:store\/)?(?:[a-z]{2}(?:-[A-Z]{2})?\/)?(?:p|product)\/([a-z0-9-]+)/i);
  if (!m) return null;
  const slug = m[1].replace(/-[0-9a-f]{6}$/i, '');
  return { url: `https://store.epicgames.com/pt-BR/p/${m[1]}`, name: slug.replace(/-/g, ' ').trim() };
}

const titleCase = (s) => s.replace(/\b\w/g, (c) => c.toUpperCase());

const collator = new Intl.Collator('pt-BR', { sensitivity: 'base', numeric: true });

const formatMoney = (p) =>
  p ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: p.currency || 'BRL' }).format(p.amount) : '';

/* ---------------- API ---------------- */

async function api(path, { method = 'GET', body } = {}) {
  const res = await fetch(path, {
    method,
    headers: { Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
    credentials: 'same-origin',
  });
  const type = res.headers.get('content-type') || '';
  if (!type.includes('application/json')) throw new Error('offline');
  const data = await res.json();
  if (!res.ok) throw Object.assign(new Error(data.error || `Erro ${res.status}`), { status: res.status });
  return data;
}

const isOffline = (e) => e.message === 'offline' || e instanceof TypeError;

/* ---------------- storage ---------------- */

// The "list data" (favorites, added, edited, hidden) lives in the browser while signed out
// and in the Steam account while signed in. Display prefs always stay in the browser.

const emptyLibrary = () => ({ favorites: [], custom: [], hidden: [], overrides: {} });
const defaultPrefs = () => ({
  sort: 'name',
  category: 'all',
  onlyFav: false,
  onlyOwned: false,
  onlySale: false,
  onlyWish: false,
  playWith: [],
});

function sanitizeLibrary(s) {
  if (!s || typeof s !== 'object') return emptyLibrary();
  const arr = (v) => (Array.isArray(v) ? v : []);
  return {
    favorites: arr(s.favorites).filter((x) => typeof x === 'string'),
    hidden: arr(s.hidden).filter((x) => typeof x === 'string'),
    custom: arr(s.custom).filter((g) => g && typeof g.id === 'string' && typeof g.name === 'string'),
    overrides: s.overrides && typeof s.overrides === 'object' ? s.overrides : {},
  };
}

const libraryOf = ({ favorites, custom, hidden, overrides }) => ({ favorites, custom, hidden, overrides });

const hasLibraryData = (lib) =>
  lib.favorites.length || lib.custom.length || lib.hidden.length || Object.keys(lib.overrides).length;

function loadLocal() {
  let s = null;
  try {
    s = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
  } catch {}
  const prefs = { ...defaultPrefs(), ...(s?.prefs && typeof s.prefs === 'object' ? s.prefs : {}) };
  prefs.playWith = Array.isArray(prefs.playWith) ? prefs.playWith.filter((x) => typeof x === 'string') : [];
  return { ...sanitizeLibrary(s), prefs };
}

// Writes the browser copy (prefs, plus the list data while signed out).
function saveStore() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.local));
  } catch {
    if (!auth.user) toast('Não deu para salvar neste navegador (modo anônimo?). Entre com a Steam ou exporte um backup.');
  }
}

// Switches the active list between the browser copy and the account copy.
// Both share the same prefs object, so filters/sort persist either way.
function useLibrary(lib) {
  state.store = lib ? { ...sanitizeLibrary(lib), prefs: state.local.prefs } : state.local;
}

/* ---------------- state ---------------- */

const local = loadLocal();

const state = {
  base: [], // data/games.json
  channel: { added: [], overrides: {}, removed: [] }, // owner's edits to the list, from /api/channel
  local, // browser copy
  store: local, // active list: === local when signed out, the account's list when signed in
  q: '',
  showHidden: false,
  editing: null, // { id, source } when editing
  steamExtra: null, // description/genres from the last Steam pick
  detailId: null, // game open in the detail modal
};

const auth = {
  api: true, // false when the site is hosted without the Worker
  user: null,
  manual: [], // [{ key, platform }]
  steamAppids: new Set(),
  counts: {}, // key -> number of owners
  owners: {}, // key -> [steam ids] of everyone who has it
  members: null, // people who can be picked in "Jogar com quem?"
  deals: {}, // key -> current sale { cut, shop, price, regular, url, expiry }
  wishlist: new Set(), // appids on the signed-in person's Steam wishlist
  wanted: {}, // key -> number of people with it on their Steam wishlist
};

const hasDeals = () => Object.keys(auth.deals).length > 0;

function dealTitle(d) {
  const shop = d.shop === 'epic' ? 'Epic' : 'Steam';
  const until = d.expiry ? ` até ${new Date(d.expiry).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })}` : '';
  return `${shop}: ${formatMoney(d.price)} (de ${formatMoney(d.regular)})${until}`;
}

// Steam ids picked in "Jogar com quem?" (only meaningful with the API).
const playWith = () => (auth.api ? state.store.prefs.playWith : []);

// Has everyone picked in "Jogar com quem?" got this game?
const everyoneHas = (g, ids) => ids.every((id) => auth.owners[g.key]?.includes(id));

function setMe(data) {
  auth.user = data.user;
  auth.manual = data.owned.manual;
  auth.steamAppids = new Set(data.owned.steamAppids);
  auth.wishlist = new Set(data.wishlist || []);
  if (data.library) useLibrary(data.library);
  else if (!data.user) useLibrary(null);
}

// Session gone (logout or expired): back to the browser copy.
function signOutLocally() {
  auth.user = null;
  auth.manual = [];
  auth.steamAppids = new Set();
  auth.wishlist = new Set();
  state.local.prefs.onlyOwned = false;
  state.local.prefs.onlyWish = false;
  useLibrary(null);
  saveStore();
}

// Saves a list change: always the browser copy (prefs), and the account when signed in.
// Requests go one at a time so quick toggles reach the server in order.
let syncQueue = Promise.resolve();
function commit(path, body) {
  saveStore();
  if (!auth.user) return;
  syncQueue = syncQueue.then(async () => {
    if (!auth.user) return;
    try {
      await api(path, { method: 'POST', body });
    } catch (e) {
      await handleSyncError(e);
    }
  });
}

async function handleSyncError(e) {
  if (e.status === 401) {
    signOutLocally();
    toast('Sua sessão expirou. Entre com a Steam de novo para salvar na sua conta.');
  } else {
    toast(isOffline(e) ? 'Sem conexão: a alteração não foi salva' : e.message);
    await loadMe(); // reload the account's list so the screen matches what is saved
  }
  renderAccount();
  syncToolbar();
  refreshAll();
}

function myOwnership(g) {
  const key = gameKey(g);
  const platforms = new Set(auth.manual.filter((m) => m.key === key).map((m) => m.platform));
  const appid = steamAppId(g.steamUrl);
  const autoSteam = !!(appid && auth.steamAppids.has(Number(appid)));
  if (autoSteam) platforms.add('steam');
  return { platforms, autoSteam };
}

const isOwnerUser = () => !!auth.user?.isOwner;

// The list everyone shares ("base"): games.json + the owner's edits (added, edited, removed),
// then each person's own edits on top. Games a person added that are now in the shared list
// are shown once, as the shared game (keeping the person's favorite).
function allGames() {
  const { store, channel } = state;
  const favs = new Set(store.favorites);
  const hidden = new Set(store.hidden);
  const removed = new Set(channel.removed);
  const showRemoved = isOwnerUser() && state.showHidden;

  const base = [
    ...state.base.map((g) => ({ ...g, ...(channel.overrides[g.id] || {}) })),
    ...channel.added.map((g) => ({ ...g, channelAdded: true })),
  ]
    .filter((g) => showRemoved || !removed.has(g.id))
    .map((g) => ({ ...g, ...(store.overrides[g.id] || {}), source: 'base', removed: removed.has(g.id) }));

  const byAppid = new Map();
  const byName = new Map();
  for (const g of base) {
    const appid = steamAppId(g.steamUrl);
    if (appid) byAppid.set(appid, g);
    byName.set(compact(g.name), g);
  }
  const favIds = new Map(base.map((g) => [g.id, [g.id]])); // ids whose favorite counts for each game
  const custom = [];
  for (const g of store.custom) {
    const same = byAppid.get(steamAppId(g.steamUrl)) || byName.get(compact(g.name));
    if (same) favIds.get(same.id).push(g.id);
    else custom.push({ ...g, source: 'custom' });
  }

  return [...base, ...custom].map((g) => {
    const ids = favIds.get(g.id) || [g.id];
    const game = {
      ...g,
      category: CATEGORY_BY_ID[g.category] ? g.category : 'outros',
      tags: Array.isArray(g.tags) ? g.tags : [],
      genres: Array.isArray(g.genres) ? g.genres : [],
      favIds: ids.filter((id) => favs.has(id)),
      hidden: hidden.has(g.id),
    };
    game.fav = game.favIds.length > 0;
    game.key = gameKey(game);
    game.owned = auth.user ? myOwnership(game).platforms.size > 0 : false;
    game.ownersCount = auth.counts[game.key] || 0;
    game.deal = auth.deals[game.key] || null;
    const appid = steamAppId(game.steamUrl);
    game.wished = !!(auth.user && appid && auth.wishlist.has(Number(appid)));
    game.wantedCount = auth.wanted[game.key] || 0;
    return game;
  });
}

const findGame = (id) => allGames().find((g) => g.id === id);

/* ---------------- direct links (?jogo=…) ---------------- */

// Base games link by their id. Games someone added link by Steam appid ("steam-620"), so the
// link also works for other people who have the same game; otherwise by their own id.
function linkId(g) {
  const appid = steamAppId(g.steamUrl);
  return g.source === 'custom' && appid ? `steam-${appid}` : g.id;
}

function findByLinkId(value) {
  const games = allGames();
  const appid = (String(value).match(/^steam-(\d+)$/) || [])[1];
  return (
    games.find((g) => g.id === value) ||
    (appid && (games.find((g) => g.source === 'base' && steamAppId(g.steamUrl) === appid) ||
      games.find((g) => steamAppId(g.steamUrl) === appid)))
  );
}

const gameUrl = (g) => `${location.origin}/?jogo=${encodeURIComponent(linkId(g))}`;

// Keeps the address bar in sync with the open game, so it can be copied or reloaded.
function setUrlGame(g) {
  const url = new URL(location.href);
  if (g) url.searchParams.set('jogo', linkId(g));
  else url.searchParams.delete('jogo');
  if (url.href !== location.href) history.replaceState(null, '', url);
}

function openFromUrl() {
  const value = new URLSearchParams(location.search).get('jogo');
  if (!value) return;
  const g = findByLinkId(value);
  if (g) openDetail(g.id);
  else {
    setUrlGame(null);
    toast('Esse jogo não está na lista.');
  }
}

async function copyGameLink(g) {
  const url = gameUrl(g);
  try {
    await navigator.clipboard.writeText(url);
    toast(`Link de ${g.name} copiado`);
  } catch {
    toast(url); // clipboard blocked: show it so it can be copied by hand
  }
}

function haystack(g) {
  const tagLabels = g.tags.map((t) => TAGS[t]?.label || '');
  return norm([g.name, g.note, CATEGORY_BY_ID[g.category]?.label, ...g.genres, ...tagLabels].join(' '));
}

function matchesQuery(g, q) {
  if (!q) return true;
  const h = haystack(g);
  return q.split(' ').every((word) => h.includes(word));
}

function sortGames(list) {
  const sort = state.store.prefs.sort;
  return list.sort((a, b) => {
    if (sort === 'fav' && a.fav !== b.fav) return a.fav ? -1 : 1;
    if (sort === 'owners' && a.ownersCount !== b.ownersCount) return b.ownersCount - a.ownersCount;
    if (sort === 'sale' && (a.deal?.cut || 0) !== (b.deal?.cut || 0)) return (b.deal?.cut || 0) - (a.deal?.cut || 0);
    if (sort === 'recent' && (a.addedAt || 0) !== (b.addedAt || 0)) return (b.addedAt || 0) - (a.addedAt || 0);
    return collator.compare(a.name, b.name);
  });
}

/* ---------------- rendering: grid ---------------- */

const main = $('#main');

function tagsHtml(g, max = 5) {
  const specific = g.tags.filter((t) => TAGS[t]);
  const tags = specific.map((t) => `<span class="tag ${TAGS[t].cls || ''}">${TAGS[t].label}</span>`);
  if (!tags.length && g.tags.includes('multiplayer')) tags.push('<span class="tag">Multijogador</span>');
  return tags.slice(0, max).join('');
}

function storeLinksHtml(g, withLabel = false) {
  const steam = safeUrl(g.steamUrl);
  const epic = safeUrl(g.epicUrl) || epicSearchUrl(g.name);
  return `
    ${steam ? `<a class="store-link steam${withLabel ? ' with-label' : ''}" href="${esc(steam)}" target="_blank" rel="noopener" title="Ver na Steam" aria-label="Ver ${esc(g.name)} na Steam">${LOGO('steam')}${withLabel ? 'Steam' : ''}</a>` : ''}
    <a class="store-link epic${withLabel ? ' with-label' : ''}" href="${esc(epic)}" target="_blank" rel="noopener" title="Ver na Epic Games Store" aria-label="Ver ${esc(g.name)} na Epic Games Store">${LOGO('epic')}${withLabel ? 'Epic' : ''}</a>`;
}

function cardHtml(g) {
  const img = safeUrl(g.image);
  return `
  <article class="card${g.fav ? ' is-fav' : ''}${g.hidden || g.removed ? ' is-hidden' : ''}" data-id="${esc(g.id)}">
    <div class="card-media">
      ${img ? `<img src="${esc(img)}" alt="" loading="lazy" decoding="async">` : `<span class="placeholder">${esc(g.name)}</span>`}
      <div class="badges">
        ${g.deal ? `<span class="badge badge-sale" title="${esc(dealTitle(g.deal))}">-${g.deal.cut}%</span>` : ''}
        ${g.wished ? `<span class="badge badge-wish" title="Na sua lista de desejos da Steam" aria-label="Na sua lista de desejos">${ICON.heart}</span>` : ''}
        ${g.owned ? `<span class="badge badge-owned">${ICON.check}Você tem</span>` : ''}
        ${g.ownersCount ? `<span class="badge" title="${g.ownersCount} ${g.ownersCount === 1 ? 'pessoa tem' : 'pessoas têm'} este jogo">${ICON.users}${g.ownersCount}</span>` : ''}
        ${g.source === 'custom' ? '<span class="badge badge-custom">Adicionado</span>' : ''}
        ${g.hidden ? '<span class="badge">Oculto</span>' : ''}
        ${g.removed ? '<span class="badge badge-removed">Fora do canal</span>' : ''}
      </div>
      <button class="fav-btn" type="button" data-action="fav" aria-pressed="${g.fav}"
        aria-label="${g.fav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}: ${esc(g.name)}">${ICON.star}</button>
    </div>
    <div class="card-body">
      <h3 class="card-title"><button type="button" class="card-open" data-action="open">${esc(g.name)}</button></h3>
      ${g.note ? `<p class="card-note">${esc(g.note)}</p>` : ''}
      <div class="tags">${tagsHtml(g)}</div>
      <div class="card-footer">
        ${storeLinksHtml(g)}
        <span class="card-tools">
          <button class="icon-btn" type="button" data-action="edit" title="Editar" aria-label="Editar ${esc(g.name)}">${ICON.edit}</button>
          ${
            g.source === 'custom'
              ? `<button class="icon-btn" type="button" data-action="remove" title="Remover" aria-label="Remover ${esc(g.name)}">${ICON.trash}</button>`
              : `<button class="icon-btn" type="button" data-action="hide" title="${g.hidden ? 'Mostrar' : 'Ocultar'}" aria-label="${g.hidden ? 'Mostrar' : 'Ocultar'} ${esc(g.name)}">${g.hidden ? ICON.eye : ICON.eyeOff}</button>`
          }
        </span>
      </div>
    </div>
  </article>`;
}

function render() {
  const { prefs } = state.store;
  const q = norm(state.q);
  const games = allGames();
  const onlyOwned = prefs.onlyOwned && !!auth.user;
  const people = playWith();
  const onlySale = prefs.onlySale && hasDeals();
  const onlyWish = prefs.onlyWish && auth.wishlist.size > 0;

  const pool = games.filter(
    (g) =>
      (state.showHidden || !g.hidden) &&
      (!prefs.onlyFav || g.fav) &&
      (!onlyOwned || g.owned) &&
      (!people.length || everyoneHas(g, people)) &&
      (!onlySale || g.deal) &&
      (!onlyWish || g.wished) &&
      matchesQuery(g, q),
  );

  renderChips(pool);
  renderStats(games);

  const visible = sortGames(pool.filter((g) => prefs.category === 'all' || g.category === prefs.category));

  if (!visible.length) {
    let msg = 'Nenhum jogo encontrado com esses filtros.';
    if (prefs.onlyFav && !games.some((g) => g.fav)) msg = 'Você ainda não marcou favoritos. Clique na ★ de um jogo.';
    else if (onlyOwned && !games.some((g) => g.owned)) msg = 'Você ainda não marcou nenhum jogo como seu. Abra um jogo e use “Eu tenho”.';
    else if (onlySale && !games.some((g) => g.deal)) msg = 'Nenhum jogo da lista está em promoção agora.';
    else if (onlyWish && !games.some((g) => g.wished)) msg = 'Nenhum jogo desta lista está na sua lista de desejos da Steam.';
    else if (people.length && !games.some((g) => everyoneHas(g, people)))
      msg = 'Nenhum jogo que todas essas pessoas têm. Tente tirar alguém em “Jogar com”.';
    main.innerHTML = `
      <div class="empty">
        <img src="assets/logo.png" alt="">
        <strong>Nada por aqui</strong>
        ${msg}
      </div>`;
    return;
  }

  const groups = CATEGORIES.map((c) => ({ ...c, games: visible.filter((g) => g.category === c.id) })).filter(
    (c) => c.games.length,
  );

  main.innerHTML = groups
    .map(
      (c) => `
      <section class="group" aria-labelledby="h-${c.id}">
        <div class="panel">
          <span class="panel-icon">${c.icon}</span>
          <h2 class="panel-title" id="h-${c.id}">${esc(c.title || c.label)}
            <span class="panel-count">${c.games.length} ${c.games.length === 1 ? 'jogo' : 'jogos'}</span>
          </h2>
        </div>
        <div class="grid">${c.games.map(cardHtml).join('')}</div>
      </section>`,
    )
    .join('');
}

function renderChips(pool) {
  const { category } = state.store.prefs;
  const count = (id) => (id === 'all' ? pool.length : pool.filter((g) => g.category === id).length);
  const chips = [{ id: 'all', label: 'Todos' }, ...CATEGORIES];
  $('#chips').innerHTML = chips
    .map(
      (c) => `<button class="chip" type="button" role="tab" data-category="${c.id}" aria-selected="${category === c.id}">
        ${esc(c.label)} <span class="count">${count(c.id)}</span></button>`,
    )
    .join('');
}

function renderStats(games) {
  const shown = games.filter((g) => !g.hidden);
  const favs = shown.filter((g) => g.fav).length;
  const custom = shown.filter((g) => g.source === 'custom').length;
  const owned = shown.filter((g) => g.owned).length;
  const hidden = games.length - shown.length;
  const onSale = shown.filter((g) => g.deal).length;
  const wishOnSale = shown.filter((g) => g.wished && g.deal).length;
  $('#stats').innerHTML =
    `<strong>${shown.length}</strong> jogos · <strong>${favs}</strong> favoritos` +
    (auth.user ? ` · você tem <strong>${owned}</strong>` : '') +
    (custom ? ` · <strong>${custom}</strong> adicionados por você` : '') +
    (onSale ? ` · <strong>${onSale}</strong> em promoção` : '') +
    (wishOnSale
      ? ` · <strong class="wish-sale">${wishOnSale}</strong> da sua lista de desejos ${wishOnSale === 1 ? 'está' : 'estão'} em promoção`
      : '');
  $('#hidden-count').textContent = hidden ? `${hidden} ${hidden === 1 ? 'jogo oculto' : 'jogos ocultos'}` : 'Nenhum jogo oculto';
}

function syncToolbar() {
  const { prefs } = state.store;
  $('#sort').value = prefs.sort;
  $('#btn-only-fav').setAttribute('aria-pressed', String(!!prefs.onlyFav));
  $('#btn-only-owned').setAttribute('aria-pressed', String(!!prefs.onlyOwned));
  $('#btn-only-owned').hidden = !auth.user;
  $('#sort-owners').hidden = !auth.api;
  $('#btn-suggestions').hidden = !isOwnerUser();
  $('#btn-mine').hidden = !auth.user;
  $('#btn-only-sale').hidden = !hasDeals();
  $('#btn-only-wish').hidden = !(auth.user && auth.wishlist.size);
  $('#btn-only-wish').setAttribute('aria-pressed', String(!!prefs.onlyWish && auth.wishlist.size > 0));
  $('#btn-only-sale').setAttribute('aria-pressed', String(!!prefs.onlySale && hasDeals()));
  $('#sort-sale').hidden = !hasDeals();
  const n = playWith().length;
  $('#btn-play-with').hidden = !auth.api;
  $('#btn-play-with').setAttribute('aria-pressed', String(n > 0));
  $('#play-with-label').textContent = n ? `Com ${n} ${n === 1 ? 'pessoa' : 'pessoas'}` : 'Jogar com';
  $('#reset-hint').textContent = auth.user
    ? 'Apaga favoritos, adições e edições da sua conta'
    : 'Apaga favoritos, adições e edições deste navegador';
}

