/* ---------------- toast ---------------- */

// The toast is a popover so it shows in the browser's top layer, above an open modal
// <dialog> and its blurred backdrop. Re-showing it puts it above the newest dialog.
const toastEl = $('#toast');
const popoverSupported = typeof toastEl.showPopover === 'function';
if (!popoverSupported) toastEl.hidden = true;

function setToastVisible(visible) {
  if (!popoverSupported) {
    toastEl.hidden = !visible;
    return;
  }
  if (toastEl.matches(':popover-open')) toastEl.hidePopover();
  if (visible) toastEl.showPopover();
}

let toastTimer;
function toast(message, action) {
  const el = toastEl;
  el.innerHTML = '';
  el.append(message);
  if (action) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'toast-action';
    btn.textContent = action.label;
    btn.onclick = () => {
      action.run();
      setToastVisible(false);
    };
    el.append(btn);
  }
  setToastVisible(true);
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => setToastVisible(false), action ? 6000 : 3000);
}

/* ---------------- local actions (favorite, hide, remove, edit) ---------------- */

function toggleList(list, id) {
  const i = list.indexOf(id);
  if (i >= 0) list.splice(i, 1);
  else list.push(id);
  return i < 0;
}

function refreshAll() {
  render();
  if (state.detailId && dlgDetail.open) renderDetail(false);
}

/* ---------------- channel's list (owner) ---------------- */

async function loadChannel() {
  if (!auth.api) return;
  try {
    state.channel = await api('/api/channel');
  } catch {}
}

// Owner change to the shared list, then reload it.
async function channelRequest(path, body) {
  const res = await api(path, { method: 'POST', body });
  await loadChannel();
  return res;
}

async function removeFromChannel(game) {
  const added = state.channel.added.find((g) => g.id === game.id);
  try {
    await channelRequest('/api/channel/remove', { id: game.id });
  } catch (e) {
    return toast(e.message);
  }
  if (dlgDetail.open) dlgDetail.close();
  refreshAll();
  toast(`${game.name} saiu da lista do canal`, {
    label: 'Desfazer',
    run: async () => {
      try {
        if (added) {
          const { id: _, addedAt, ...data } = added;
          await channelRequest('/api/channel/game', { id: game.id, added: true, data });
        } else await channelRequest('/api/channel/restore', { id: game.id });
        refreshAll();
      } catch (e) {
        toast(e.message);
      }
    },
  });
}

function runAction(action, id) {
  const game = findGame(id);
  if (!game) return;
  const { store } = state;

  switch (action) {
    case 'open':
      openDetail(id);
      break;
    case 'fav': {
      // a shared game can be a favorite through a copy the person had added before
      const added = !game.fav;
      for (const favId of added ? [id] : game.favIds) {
        toggleList(store.favorites, favId);
        commit('/api/library/flag', { id: favId, flag: 'favorite', on: added });
      }
      refreshAll();
      toast(added ? `★ ${game.name} nos favoritos` : `${game.name} saiu dos favoritos`);
      break;
    }
    case 'hide': {
      const hid = toggleList(store.hidden, id);
      commit('/api/library/flag', { id, flag: 'hidden', on: hid });
      if (hid && dlgDetail.open) dlgDetail.close();
      refreshAll();
      if (hid) {
        toast(`${game.name} foi ocultado`, {
          label: 'Desfazer',
          run: () => {
            if (state.store !== store) return; // signed in/out meanwhile
            toggleList(store.hidden, id);
            commit('/api/library/flag', { id, flag: 'hidden', on: false });
            refreshAll();
          },
        });
      }
      break;
    }
    case 'remove': {
      const idx = store.custom.findIndex((g) => g.id === id);
      if (idx < 0) return;
      const [removed] = store.custom.splice(idx, 1);
      const wasFav = store.favorites.includes(id);
      store.favorites = store.favorites.filter((f) => f !== id);
      commit('/api/library/remove', { id });
      if (dlgDetail.open) dlgDetail.close();
      render();
      toast(`${game.name} removido`, {
        label: 'Desfazer',
        run: () => {
          if (state.store !== store) return; // signed in/out meanwhile
          store.custom.splice(idx, 0, removed);
          if (wasFav) store.favorites.push(id);
          const { id: _, addedAt, ...data } = removed;
          commit('/api/library/game', { id, custom: true, data, addedAt, favorite: wasFav });
          render();
        },
      });
      break;
    }
    case 'edit':
      if (dlgDetail.open) dlgDetail.close();
      openGameDialog(game);
      break;
    case 'share':
      copyGameLink(game);
      break;
    case 'channel-remove':
      removeFromChannel(game);
      break;
    case 'channel-restore':
      channelRequest('/api/channel/restore', { id })
        .then(() => {
          refreshAll();
          toast(`${game.name} voltou para a lista do canal`);
        })
        .catch((e) => toast(e.message));
      break;
  }
}

main.addEventListener('click', (e) => {
  const card = e.target.closest('.card');
  if (!card) return;
  const btn = e.target.closest('[data-action]');
  if (btn) return runAction(btn.dataset.action, card.dataset.id);
  if (e.target.closest('a')) return; // store links
  runAction('open', card.dataset.id);
});

// Broken image → name placeholder
function imageFallback(e) {
  const img = e.target;
  if (img.tagName !== 'IMG' || img.closest('.btn-user, .account-head, .owner')) return;
  const span = document.createElement('span');
  span.className = 'placeholder';
  span.textContent = img.dataset.name || img.closest('.card')?.querySelector('.card-title')?.textContent || '';
  img.replaceWith(span);
}
main.addEventListener('error', imageFallback, true);

