const detailEl = $('#detail');
const priceCache = new Map();

function openDetail(id) {
  state.detailId = id;
  renderDetail(true);
  if (!dlgDetail.open) dlgDetail.showModal();
  setUrlGame(findGame(id));
}

dlgDetail.addEventListener('close', () => {
  if (dlgDetail.open) return; // reopened with another game before this event arrived
  state.detailId = null;
  setUrlGame(null);
});
dlgDetail.addEventListener('click', (e) => {
  if (e.target === dlgDetail || e.target.closest('[data-close]')) return dlgDetail.close();
  const btn = e.target.closest('[data-action]');
  if (btn && state.detailId) runAction(btn.dataset.action, state.detailId);
  const own = e.target.closest('[data-platform]');
  if (own) toggleOwnership(own);
  if (e.target.closest('[data-open-mine]')) openMine();
});
detailEl.addEventListener('error', imageFallback, true);

