/* prices */

function priceCardHtml(store, label, url, info, itadEnabled) {
  let body;
  if (!info) {
    body =
      store === 'epic' && !itadEnabled
        ? '<span class="price-muted">Ver preço na loja</span>'
        : `<span class="price-muted">${store === 'epic' ? 'Sem preço na Epic' : 'Sem preço'}</span>`;
  } else if (info.free) {
    body = '<span class="price-now">Grátis</span>';
  } else if (info.unavailable || !info.price) {
    body = '<span class="price-muted">Indisponível para compra</span>';
  } else {
    const onSale = info.discount > 0;
    body = `
      <span class="price-now">${formatMoney(info.price)}</span>
      ${onSale ? `<span class="price-old">${formatMoney(info.regular)}</span>` : ''}`;
  }
  const discount = info && info.discount > 0 ? `<span class="discount">-${info.discount}%</span>` : '';
  const low =
    info?.storeLow && info.price && info.storeLow.amount < info.price.amount
      ? `<span class="price-low">Menor na loja: ${formatMoney(info.storeLow)}</span>`
      : info?.storeLow && info.price && info.storeLow.amount >= info.price.amount && info.discount > 0
        ? '<span class="price-low good">Menor preço da loja!</span>'
        : '';
  return `
    <a class="price-card ${store}${info && info.discount > 0 ? ' on-sale' : ''}" href="${esc(url)}" target="_blank" rel="noopener">
      ${LOGO(store)}
      <span class="price-info">
        <span class="store-name">${label}</span>
        <span class="price-row">${body}</span>
        ${low}
      </span>
      ${discount}
    </a>`;
}

function pricesHtml(g, data) {
  if (!auth.api) {
    return `<p class="hint">Preços indisponíveis nesta hospedagem.</p>`;
  }
  if (data === undefined) {
    return `<div class="price-card skeleton"></div><div class="price-card skeleton"></div>`;
  }
  if (data === null) return '<p class="hint error">Não foi possível carregar os preços agora.</p>';

  const steamUrl = safeUrl(g.steamUrl) || data.steam?.url;
  const epicUrl = safeUrl(g.epicUrl) || epicSearchUrl(g.name);
  const cards = [];
  if (steamUrl || data.steam) cards.push(priceCardHtml('steam', 'Steam', steamUrl || '#', data.steam, data.itad));
  cards.push(priceCardHtml('epic', 'Epic Games', data.epic?.url && !safeUrl(g.epicUrl) ? data.epic.url : epicUrl, data.epic, data.itad));

  const footer = data.historyLow
    ? `<p class="price-history">${ICON.trend}Menor preço já registrado: <strong>${formatMoney(data.historyLow)}</strong>
        ${data.itadUrl ? `· <a href="${esc(safeUrl(data.itadUrl))}" target="_blank" rel="noopener">histórico no IsThereAnyDeal</a>` : ''}</p>`
    : !data.itad
      ? '<p class="hint">Preço da Epic e histórico aparecem quando a chave do IsThereAnyDeal estiver configurada.</p>'
      : '';
  return cards.join('') + footer;
}

async function loadPrices(g) {
  const appid = steamAppId(g.steamUrl);
  const params = appid ? `appid=${appid}` : `title=${encodeURIComponent(g.name)}`;
  try {
    const data = await api(`/api/prices?${params}`);
    priceCache.set(g.key, data);
  } catch (e) {
    if (isOffline(e)) auth.api = false;
    priceCache.set(g.key, null);
  }
  if (state.detailId === g.id) {
    const el = $('#detail-prices');
    if (el) el.innerHTML = pricesHtml(g, priceCache.get(g.key));
  }
}

/* ownership */

function ownHtml(g) {
  if (!auth.user) {
    return `
      <div class="own-login">
        <p>Entre com a Steam para marcar que você tem este jogo. Seu nome e avatar aparecem em “Quem tem”.</p>
        <a class="btn btn-steam" href="/api/auth/login">${LOGO('steam')}Entrar com Steam</a>
      </div>`;
  }
  const { platforms, autoSteam } = myOwnership(g);
  return `
    <div class="own-toggles" role="group" aria-label="Plataformas em que você tem o jogo">
      ${PLATFORMS.map((p) => {
        const on = platforms.has(p.id);
        const locked = p.id === 'steam' && autoSteam;
        return `<button type="button" class="own-toggle ${p.id}" data-platform="${p.id}" aria-pressed="${on}"
          aria-label="Tenho na ${p.label}${locked ? ' (detectado na sua biblioteca Steam)' : ''}" ${locked ? 'disabled title="Detectado na sua biblioteca Steam"' : ''}>
          ${p.id === 'outra' ? ICON.gamepad : LOGO(p.id)}${p.label}${on ? ICON.check : ''}
        </button>`;
      }).join('')}
    </div>
    ${autoSteam ? '<p class="hint">Steam detectado automaticamente na sua biblioteca.</p>' : ''}
    <button type="button" class="link-btn" data-open-mine>Marcar vários jogos de uma vez ou importar da Epic</button>`;
}

async function toggleOwnership(btn) {
  const g = findGame(state.detailId);
  if (!g || btn.disabled) return;
  const platform = btn.dataset.platform;
  const owned = btn.getAttribute('aria-pressed') !== 'true';
  btn.disabled = true;
  try {
    setMe(await api('/api/ownership', { method: 'POST', body: { key: g.key, platform, owned } }));
    await loadCounts();
    refreshAll();
    toast(owned ? `Marcado: você tem ${g.name}` : 'Marcação removida');
  } catch (e) {
    btn.disabled = false;
    if (e.status === 401) {
      signOutLocally();
      renderAccount();
      syncToolbar();
      refreshAll();
      toast('Sua sessão expirou. Entre com a Steam de novo.');
    } else toast(isOffline(e) ? 'Sem conexão com o servidor' : e.message);
  }
}

const personHtml = (o) => {
  const avatar = safeUrl(o.avatar);
  const profile = safeUrl(o.profileUrl);
  return `<li class="owner">
    <a href="${esc(profile)}" target="_blank" rel="noopener" class="owner-link">
      ${avatar ? `<img src="${esc(avatar)}" alt="" width="36" height="36" loading="lazy">` : '<span class="owner-avatar"></span>'}
      <span class="owner-name">${esc(o.name)}${o.name === auth.user?.name ? ' <small>(você)</small>' : ''}</span>
    </a>
  </li>`;
};

async function loadOwners(g) {
  let owners = null;
  let wanters = [];
  try {
    ({ owners, wanters = [] } = await api(`/api/owners?key=${encodeURIComponent(g.key)}`));
  } catch {}
  if (state.detailId !== g.id) return;
  const list = $('#detail-owners');
  if (!list) return;
  // "Quem quer": people with it on their Steam wishlist
  $('#sec-wanters-wrap').hidden = !wanters.length;
  $('#wanters-count').textContent = wanters.length ? `(${wanters.length})` : '';
  $('#detail-wanters').innerHTML = wanters.map(personHtml).join('');
  $('#owners-count').textContent = owners?.length ? `(${owners.length})` : '';
  if (!owners) {
    list.innerHTML = '<li class="hint error">Não foi possível carregar.</li>';
    return;
  }
  if (!owners.length) {
    list.innerHTML = '<li class="hint">Ninguém marcou ainda. Seja o primeiro!</li>';
    return;
  }
  const meName = auth.user?.name;
  list.innerHTML = owners
    .map((o) => {
      const avatar = safeUrl(o.avatar);
      const profile = safeUrl(o.profileUrl);
      return `<li class="owner">
        <a href="${esc(profile)}" target="_blank" rel="noopener" class="owner-link">
          ${avatar ? `<img src="${esc(avatar)}" alt="" width="36" height="36" loading="lazy">` : '<span class="owner-avatar"></span>'}
          <span class="owner-name">${esc(o.name)}${o.name === meName ? ' <small>(você)</small>' : ''}</span>
        </a>
        <span class="owner-platforms">
          ${o.platforms
            .map((p) =>
              p.id === 'outra'
                ? `<span class="mini-plat" title="Outra plataforma">${ICON.gamepad}</span>`
                : `<span class="mini-plat ${p.id}" title="${p.id === 'steam' ? 'Steam' : 'Epic'}${p.auto ? ' (detectado)' : ''}">${LOGO(p.id)}</span>`,
            )
            .join('')}
        </span>
      </li>`;
    })
    .join('');
}

