async function loadMe() {
  try {
    setMe(await api('/api/me'));
    auth.api = true;
  } catch (e) {
    if (isOffline(e)) auth.api = false;
    if (auth.user) signOutLocally();
  }
}

// First load after signing in: move what this browser had (favorites, added games…) into the
// account, then clear the browser copy. Added games the account already has are skipped.
// Returns a message for the toast, or null.
async function moveLocalToAccount() {
  const lib = libraryOf(state.local);
  if (!auth.user || !hasLibraryData(lib)) return null;
  const inAccount = new Set(
    state.store.custom.flatMap((g) => [compact(g.name), steamAppId(g.steamUrl)].filter(Boolean)),
  );
  const custom = lib.custom.filter((g) => !inAccount.has(compact(g.name)) && !inAccount.has(steamAppId(g.steamUrl)));
  const skipped = new Set(lib.custom.filter((g) => !custom.includes(g)).map((g) => g.id));
  const keep = (ids) => ids.filter((id) => !skipped.has(id));
  const body = { mode: 'merge', ...lib, custom, favorites: keep(lib.favorites), hidden: keep(lib.hidden) };
  try {
    const { library } = await api('/api/library/import', { method: 'POST', body });
    Object.assign(state.local, emptyLibrary());
    saveStore();
    useLibrary(library);
    return 'Seus favoritos e jogos deste navegador foram salvos na sua conta Steam';
  } catch {
    return null; // keep the browser copy and try again next time
  }
}

// Current sales for every game in the list (one request; cached on the server for an hour).
async function loadDeals() {
  if (!auth.api) return;
  const seen = new Set();
  const games = [];
  for (const g of allGames()) {
    if (seen.has(g.key)) continue;
    seen.add(g.key);
    games.push({ key: g.key, appid: steamAppId(g.steamUrl), title: g.name });
  }
  try {
    ({ deals: auth.deals } = await api('/api/deals', { method: 'POST', body: { games } }));
  } catch {
    auth.deals = {};
  }
  syncToolbar();
  render();
}

async function loadCounts() {
  if (!auth.api) return;
  try {
    const keys = [...new Set(allGames().map((g) => g.key))];
    const { counts, owners, wanted } = await api('/api/owners/counts', { method: 'POST', body: { keys } });
    auth.counts = counts;
    auth.owners = owners || {};
    auth.wanted = wanted || {};
  } catch {}
}

document.addEventListener('click', async (e) => {
  if (e.target.closest('#btn-user')) dlgMenu.showModal();

  if (e.target.closest('#btn-sync')) {
    const btn = e.target.closest('#btn-sync');
    btn.disabled = true;
    btn.textContent = 'Sincronizando…';
    try {
      setMe(await api('/api/me/sync', { method: 'POST', body: {} }));
      await loadCounts();
      renderAccount();
      syncToolbar();
      refreshAll();
      toast(
        auth.user.libraryVisible
          ? `Biblioteca sincronizada: ${auth.steamAppids.size} jogos, ${auth.wishlist.size} na lista de desejos`
          : 'Sua biblioteca Steam está privada',
      );
    } catch (e2) {
      toast(e2.message);
      btn.disabled = false;
      btn.textContent = 'Sincronizar biblioteca';
    }
  }

  const del = e.target.closest('#btn-delete-account');
  if (del) {
    if (!del.dataset.armed) {
      del.dataset.armed = '1';
      del.textContent = 'Clique de novo para apagar tudo';
      setTimeout(() => {
        if (!del.isConnected) return;
        delete del.dataset.armed;
        del.textContent = 'Apagar minha conta';
      }, 4000);
      return;
    }
    del.disabled = true;
    await syncQueue;
    try {
      await api('/api/me', { method: 'DELETE', body: {} });
    } catch (err) {
      del.disabled = false;
      toast(isOffline(err) ? 'Sem conexão com o servidor' : err.message);
      return;
    }
    signOutLocally();
    dlgMenu.close();
    await loadCounts();
    renderAccount();
    syncToolbar();
    refreshAll();
    toast('Sua conta e seus dados foram apagados');
  }

  if (e.target.closest('#btn-logout')) {
    await syncQueue; // let pending changes reach the account first
    try {
      await api('/api/auth/logout', { method: 'POST', body: {} });
    } catch {}
    signOutLocally();
    dlgMenu.close();
    renderAccount();
    syncToolbar();
    refreshAll();
    toast('Você saiu');
  }
});

