const dlgGame = $('#dlg-game');
const form = $('#form-game');
const steamQ = $('#steam-q');
const steamStatus = $('#steam-status');
const steamResults = $('#steam-results');

$('#field-category').innerHTML = CATEGORIES.map((c) => `<option value="${c.id}">${esc(c.title || c.label)}</option>`).join('');
$('#tag-picker').innerHTML = Object.entries(TAGS)
  .map(
    ([id, t]) => `<label><input type="checkbox" name="tags" value="${id}"><span class="chip">${esc(t.label)}</span></label>`,
  )
  .join('');

const EDIT_HINT = 'Buscar de novo na Steam substitui imagem, links e modos.';

// Status line under the search when nothing needs saying (keeps the edit hint while editing).
const idleStatus = () => setStatus(state.editing ? EDIT_HINT : '');

// Message shown inside the results dropdown (over the form, so the modal doesn't grow).
function setResultsMessage(text) {
  steamResults.hidden = false;
  steamResults.innerHTML = `<li class="results-msg">${esc(text)}</li>`;
}

function setStatus(text, kind = '') {
  steamStatus.textContent = text;
  steamStatus.className = `hint ${kind}`;
}

function updatePreview() {
  const url = safeUrl(form.image.value.trim());
  const img = $('#preview-img');
  if (url) {
    img.src = url;
    img.hidden = false;
    $('#preview-empty').hidden = true;
  } else {
    img.removeAttribute('src');
    img.hidden = true;
    $('#preview-empty').hidden = false;
  }
}

$('#preview-img').addEventListener('error', () => {
  $('#preview-img').hidden = true;
  $('#preview-empty').hidden = false;
  $('#preview-empty').textContent = 'Imagem não carregou';
});

function setTags(tags = []) {
  form.querySelectorAll('input[name="tags"]').forEach((cb) => (cb.checked = tags.includes(cb.value)));
}

function findExisting({ name, appid }, exceptId) {
  return allGames().find(
    (g) =>
      g.id !== exceptId &&
      ((appid && steamAppId(g.steamUrl) === String(appid)) || (name && compact(g.name) === compact(name))),
  );
}

function openGameDialog(game = null) {
  form.reset();
  state.editing = game ? { id: game.id, source: game.source, channelAdded: !!game.channelAdded } : null;
  state.steamExtra = null;
  $('#dlg-game-title').textContent = game ? 'Editar jogo' : 'Adicionar jogo';
  $('#btn-save').textContent = game ? 'Salvar alterações' : 'Adicionar';
  $('#form-error').textContent = '';
  $('#preview-empty').textContent = 'Sem imagem';
  steamResults.innerHTML = '';
  idleStatus();
  $('#steam-search').hidden = !auth.api;

  // The owner saves to the channel's list (everyone sees it) unless they uncheck it.
  const owner = isOwnerUser();
  $('#channel-field').hidden = !owner;
  if (owner) {
    form.channel.checked = !game || game.source === 'base';
    $('#channel-hint').textContent = !game
      ? 'Todo mundo vê este jogo. Desmarque para adicionar só para você.'
      : game.source === 'base'
        ? 'As alterações valem para todo mundo. Desmarque para mudar só para você.'
        : 'Marque para levar este jogo para a lista do canal.';
  }

  if (game) {
    form.name.value = game.name || '';
    form.category.value = game.category;
    form.image.value = game.image || '';
    form.steamUrl.value = game.steamUrl || '';
    form.epicUrl.value = game.epicUrl || '';
    form.note.value = game.note || '';
    setTags(game.tags);
  } else {
    const cat = state.store.prefs.category;
    form.category.value = CATEGORY_BY_ID[cat] ? cat : 'coop-online';
  }
  updatePreview();
  dlgGame.showModal();
  (game || !auth.api ? form.name : steamQ).focus();
}

dlgGame.addEventListener('click', (e) => {
  if (e.target.closest('[data-close]') || e.target === dlgGame) dlgGame.close();
});

form.image.addEventListener('input', () => {
  $('#preview-empty').textContent = 'Sem imagem';
  updatePreview();
});

const API_OFFLINE_MSG =
  'A busca automática não está disponível nesta hospedagem. Preencha os campos manualmente (ou rode com npm run dev).';

let steamTimer;
let steamSeq = 0;
steamQ.addEventListener('input', () => {
  clearTimeout(steamTimer);
  const q = steamQ.value.trim();
  if (q.length < 2) {
    steamResults.innerHTML = '';
    idleStatus();
    return;
  }
  steamTimer = setTimeout(() => runSteamSearch(q), 400);
});

steamQ.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    clearTimeout(steamTimer);
    const q = steamQ.value.trim();
    if (q.length >= 2) runSteamSearch(q);
  }
});

async function runSteamSearch(q) {
  const seq = ++steamSeq;
  const directId = steamAppId(q) || (/^\d{2,8}$/.test(q) ? q : null);
  if (directId) {
    steamResults.innerHTML = '';
    return pickSteam(directId);
  }

  const epic = epicLinkInfo(q);
  if (epic) {
    form.epicUrl.value = epic.url;
    form.name.value = titleCase(epic.name);
    q = epic.name;
  }

  idleStatus();
  setResultsMessage(epic ? `Link da Epic reconhecido. Procurando “${titleCase(epic.name)}” na Steam…` : 'Buscando na Steam…');
  try {
    const { items } = await api(`/api/steam/search?q=${encodeURIComponent(q)}`);
    if (seq !== steamSeq) return;
    if (!items.length) {
      steamResults.innerHTML = '';
      const title = epic ? titleCase(epic.name) : q;
      const image = await fillImageFromItad(title);
      if (seq !== steamSeq) return;
      setStatus(
        epic
          ? `Não está na Steam. Preenchi o nome e o link da Epic${image ? ' e a imagem' : '; cole uma URL de imagem se quiser'}.`
          : `Nada encontrado na Steam. ${image ? 'Achei uma imagem no IsThereAnyDeal; preencha' : 'Você pode preencher'} o resto abaixo.`,
        'warn',
      );
      return;
    }
    if (epic) {
      const exact = items.find((it) => compact(it.name) === compact(epic.name));
      if (exact) return pickSteam(exact.appid);
    }
    steamResults.hidden = false;
    steamResults.innerHTML = items
      .map((it) => {
        const exists = findExisting({ name: it.name, appid: it.appid }, state.editing?.id);
        return `<li><button type="button" class="result" data-appid="${it.appid}">
          <img src="${esc(safeUrl(it.thumb))}" alt="" loading="lazy">
          <span>${esc(it.name)}</span>
          ${exists ? '<span class="in-list">Já na lista</span>' : ''}
        </button></li>`;
      })
      .join('');
  } catch (e) {
    if (seq !== steamSeq) return;
    steamResults.innerHTML = '';
    setStatus(isOffline(e) ? API_OFFLINE_MSG : e.message, 'error');
  }
}

// Owner: saves the form to the channel's list. Returns the game id to highlight.
async function saveToChannel(editing, data) {
  const { store } = state;
  if (!editing) {
    const { id } = await channelRequest('/api/channel/game', { added: true, data });
    return id;
  }
  if (editing.source === 'base') {
    const id = editing.id;
    if (editing.channelAdded) {
      const { id: _, addedAt, ...current } = state.channel.added.find((g) => g.id === id) || {};
      await channelRequest('/api/channel/game', { id, added: true, data: { ...current, ...data } });
    } else {
      await channelRequest('/api/channel/game', { id, added: false, data: { ...(state.channel.overrides[id] || {}), ...data } });
    }
    // the owner's own edit of this game would hide the shared one
    if (store.overrides[id]) {
      delete store.overrides[id];
      commit('/api/library/game', { id, custom: false, data: {} });
    }
    return id;
  }
  // a game the owner had added only for themselves moves to the channel's list
  const mine = store.custom.find((g) => g.id === editing.id) || {};
  const { id: _, addedAt, ...current } = mine;
  const { id } = await channelRequest('/api/channel/game', { added: true, data: { ...current, ...data } });
  const wasFav = store.favorites.includes(editing.id);
  store.custom = store.custom.filter((g) => g.id !== editing.id);
  store.favorites = store.favorites.filter((f) => f !== editing.id);
  commit('/api/library/remove', { id: editing.id });
  if (wasFav) {
    store.favorites.push(id);
    commit('/api/library/flag', { id, flag: 'favorite', on: true });
  }
  return id;
}

// Games that are not on Steam (e.g. Epic exclusives) get their image from IsThereAnyDeal.
async function fillImageFromItad(title) {
  if (form.image.value.trim()) return false;
  try {
    const { image } = await api(`/api/itad/image?title=${encodeURIComponent(title)}`);
    if (!image || form.image.value.trim()) return false;
    form.image.value = image;
    updatePreview();
    return true;
  } catch {
    return false;
  }
}

steamResults.addEventListener('click', (e) => {
  const btn = e.target.closest('[data-appid]');
  if (btn) pickSteam(btn.dataset.appid, btn);
});

// The results are a dropdown over the form: close it on Esc or a click elsewhere in the
// modal, reopen it when the search field gets focus again. Arrow keys move between results.
const resultsOpen = () => !steamResults.hidden && steamResults.children.length > 0;

steamQ.addEventListener('focus', () => (steamResults.hidden = false));

steamQ.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' && resultsOpen()) {
    e.preventDefault();
    steamResults.querySelector('.result')?.focus();
  }
});

steamResults.addEventListener('keydown', (e) => {
  const items = [...steamResults.querySelectorAll('.result')];
  const i = items.indexOf(document.activeElement);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    const next = i + (e.key === 'ArrowDown' ? 1 : -1);
    (next < 0 ? steamQ : items[Math.min(next, items.length - 1)]).focus();
  }
});

dlgGame.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && resultsOpen()) {
    e.preventDefault(); // close the dropdown, not the modal
    steamResults.hidden = true;
    steamQ.focus();
  }
});

dlgGame.addEventListener('pointerdown', (e) => {
  if (resultsOpen() && !e.target.closest('#steam-search')) steamResults.hidden = true;
});

async function pickSteam(appid, btn) {
  if (btn) btn.setAttribute('aria-busy', 'true');
  setStatus('Carregando dados da Steam…');
  try {
    const d = await api(`/api/steam/details?appid=${encodeURIComponent(appid)}`);
    form.name.value = d.name;
    form.image.value = d.image || '';
    form.steamUrl.value = d.url;
    // keep a real Epic product link; replace empty or auto-generated search links
    if (!form.epicUrl.value || form.epicUrl.value.includes('/browse?q=')) form.epicUrl.value = epicSearchUrl(d.name);
    if (!state.editing) form.category.value = d.suggestedCategory;
    setTags(d.tags);
    state.steamExtra = { description: d.description, genres: d.genres };
    updatePreview();
    steamResults.innerHTML = '';
    const exists = findExisting({ name: d.name, appid: d.appid }, state.editing?.id);
    const noMulti = !d.tags.length;
    setStatus(
      exists
        ? `Atenção: “${exists.name}” já está na lista.`
        : noMulti
          ? 'Dados carregados, mas a Steam não lista modo multiplayer para este jogo. Confira antes de salvar.'
          : 'Dados carregados da Steam. Confira a categoria e salve.',
      exists || noMulti ? 'warn' : '',
    );
  } catch (e) {
    setStatus(isOffline(e) ? API_OFFLINE_MSG : e.message, 'error');
  } finally {
    if (btn) btn.removeAttribute('aria-busy');
  }
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  const err = $('#form-error');
  const name = form.name.value.trim();
  if (!name) {
    err.textContent = 'Informe o nome do jogo.';
    form.name.focus();
    return;
  }
  for (const field of ['image', 'steamUrl', 'epicUrl']) {
    const v = form[field].value.trim();
    if (v && !safeUrl(v)) {
      err.textContent = 'Os links precisam começar com https://';
      form[field].focus();
      return;
    }
  }

  const editing = state.editing;
  const dupe = findExisting({ name, appid: steamAppId(form.steamUrl.value) }, editing?.id);
  if (dupe && !editing) {
    err.textContent = `“${dupe.name}” já está na lista.`;
    return;
  }

  const data = {
    name,
    category: form.category.value,
    note: form.note.value.trim(),
    image: form.image.value.trim(),
    steamUrl: form.steamUrl.value.trim(),
    epicUrl: form.epicUrl.value.trim() || epicSearchUrl(name),
    tags: [...form.querySelectorAll('input[name="tags"]:checked')].map((cb) => cb.value),
    ...(state.steamExtra || {}),
  };

  const { store } = state;
  let id;
  let saved; // what goes to the account
  if (isOwnerUser() && form.channel.checked) {
    const btn = $('#btn-save');
    btn.disabled = true;
    try {
      id = await saveToChannel(editing, data);
    } catch (e2) {
      err.textContent = isOffline(e2) ? 'Sem conexão com o servidor.' : e2.message;
      return;
    } finally {
      btn.disabled = false;
    }
    toast(editing ? 'Lista do canal atualizada' : `${name} adicionado à lista do canal!`);
  } else if (!editing) {
    id = `c-${Date.now().toString(36)}`;
    const addedAt = Date.now();
    store.custom.push({ id, ...data, addedAt });
    saved = { id, custom: true, data, addedAt };
    toast(`${name} adicionado!`);
  } else if (editing.source === 'custom') {
    id = editing.id;
    const g = store.custom.find((x) => x.id === id);
    if (g) Object.assign(g, data);
    const { id: _, addedAt, ...full } = g || data;
    saved = { id, custom: true, data: full, addedAt };
    toast('Alterações salvas');
  } else {
    id = editing.id;
    store.overrides[id] = { ...(store.overrides[id] || {}), ...data };
    saved = { id, custom: false, data: store.overrides[id] };
    toast('Alterações salvas');
  }

  // make sure the saved game is visible
  const cat = store.prefs.category;
  if (cat !== 'all' && cat !== data.category) store.prefs.category = 'all';
  if (store.prefs.onlyFav && !store.favorites.includes(id)) store.prefs.onlyFav = false;
  store.prefs.onlyOwned = false;
  store.prefs.playWith = [];
  if (state.q) {
    state.q = '';
    $('#search').value = '';
  }

  if (saved) commit('/api/library/game', saved);
  else saveStore();
  syncToolbar();
  dlgGame.close();
  await loadCounts();
  render();
  loadDeals();

  requestAnimationFrame(() => {
    const card = main.querySelector(`.card[data-id="${CSS.escape(id)}"]`);
    if (card) {
      card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      card.animate(
        [{ boxShadow: '0 0 0 3px #f2c14e' }, { boxShadow: '0 0 0 3px transparent' }],
        { duration: 1600, easing: 'ease-out' },
      );
    }
  });
});

$('#btn-add').addEventListener('click', () => openGameDialog());

/* ---------------- options dialog ---------------- */

const dlgMenu = $('#dlg-menu');
$('#btn-menu').addEventListener('click', () => dlgMenu.showModal());
dlgMenu.addEventListener('click', (e) => {
  if (e.target.closest('[data-close]') || e.target === dlgMenu) dlgMenu.close();
});

$('#btn-export').addEventListener('click', () => {
  const { prefs, ...data } = state.store;
  const blob = new Blob([JSON.stringify({ app: 'dogworks-games', version: 1, exportedAt: new Date().toISOString(), ...data }, null, 2)], {
    type: 'application/json',
  });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `dogworks-jogos-backup-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  toast('Backup exportado');
});

$('#file-import').addEventListener('change', async (e) => {
  const file = e.target.files?.[0];
  e.target.value = '';
  if (!file) return;
  try {
    const data = JSON.parse(await file.text());
    if (!data || (!data.favorites && !data.custom)) throw new Error('formato');
    await replaceLibrary(sanitizeLibrary(data));
    await loadCounts();
    render();
    dlgMenu.close();
    toast(`Backup importado: ${state.store.favorites.length} favoritos, ${state.store.custom.length} adicionados`);
  } catch (err) {
    toast(err.status || isOffline(err) ? `Não foi possível importar: ${err.message}` : 'Arquivo inválido. Use um backup exportado por este site.');
  }
});

// Replaces the whole list (backup import / reset), in the account or in this browser.
async function replaceLibrary(lib) {
  if (auth.user) {
    await syncQueue;
    const { library } = await api('/api/library/import', { method: 'POST', body: { mode: 'replace', ...lib } });
    useLibrary(library);
  } else {
    Object.assign(state.local, lib);
    saveStore();
  }
}

$('#toggle-hidden').addEventListener('change', (e) => {
  state.showHidden = e.target.checked;
  render();
});

let resetArmed = false;
let resetTimer;
$('#btn-reset').addEventListener('click', async (e) => {
  const strong = e.currentTarget.querySelector('strong');
  if (!resetArmed) {
    resetArmed = true;
    strong.textContent = 'Clique de novo para confirmar';
    resetTimer = setTimeout(() => {
      resetArmed = false;
      strong.textContent = 'Restaurar lista original';
    }, 4000);
    return;
  }
  clearTimeout(resetTimer);
  resetArmed = false;
  strong.textContent = 'Restaurar lista original';
  try {
    await replaceLibrary(emptyLibrary());
  } catch (err) {
    toast(`Não foi possível restaurar: ${err.message}`);
    return;
  }
  Object.assign(state.store.prefs, defaultPrefs());
  saveStore();
  syncToolbar();
  render();
  dlgMenu.close();
  toast('Lista restaurada');
});

/* ---------------- boot ---------------- */

function handleLoginReturn() {
  const params = new URLSearchParams(location.search);
  const login = params.get('login');
  if (!login) return;
  const url = new URL(location.href);
  url.searchParams.delete('login');
  history.replaceState(null, '', url);
  if (login === 'ok' && auth.user) toast(`Bem-vindo, ${auth.user.name}!`);
  else if (login === 'erro') toast('Não foi possível entrar com a Steam. Tente de novo.');
}

async function boot() {
  syncToolbar();
  try {
    const res = await fetch('data/games.json');
    if (!res.ok) throw new Error(res.status);
    state.base = await res.json();
  } catch {
    main.innerHTML = '<p class="empty">Não foi possível carregar <code>data/games.json</code>.</p>';
    return;
  }
  render();

  await Promise.all([loadMe(), loadChannel()]);
  const moved = await moveLocalToAccount();
  await loadCounts();
  if (auth.api && state.store.prefs.playWith.length) await loadMembers();
  renderAccount();
  syncToolbar();
  render();
  handleLoginReturn();
  if (moved) toast(moved);
  openFromUrl();
  loadDeals(); // not awaited: the list shows first, sale badges appear when ready
}

boot();
